enum sd_cancel_mode_t {
  /// Stop the current generation as soon as possible.
  SD_CANCEL_ALL(0),

  /// Finish the current image sample, then skip additional batch latents and
  /// return completed images.
  SD_CANCEL_NEW_LATENTS(1),

  /// Clear a pending cancellation request.
  SD_CANCEL_RESET(2);

  final int value;
  const sd_cancel_mode_t(this.value);

  static sd_cancel_mode_t fromValue(int value) => switch (value) {
    0 => SD_CANCEL_ALL,
    1 => SD_CANCEL_NEW_LATENTS,
    2 => SD_CANCEL_RESET,
    _ => throw ArgumentError('Unknown value for sd_cancel_mode_t: $value'),
  };
}
